package store

import (
	"errors"
	"reflect"
	"testing"
	"time"

	"example.com/tally/internal/money"
)

var t0 = time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)

func newOrg(t *testing.T, s *Store, name string) Org {
	t.Helper()
	o, err := s.CreateOrg(name, OrgTeam, "UTC", 0, t0)
	if err != nil {
		t.Fatal(err)
	}
